            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not outside[nr][nc]):
                outside[nr][nc] = True
                q.append((nr, nc))

    # Enclosed zero components are the interiors.
    seen = [[False] * w for _ in range(h)]
    interior = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c] or seen[r][c]:
                continue
            cells = [(r, c)]
            seen[r][c] = True
            for rr, cc in cells:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                            and not outside[nr][nc] and not seen[nr][nc]):
                        seen[nr][nc] = True
                        cells.append((nr, nc))
            interior.update(cells)
            r0 = min(x for x, y in cells)
            r1 = max(x for x, y in cells)
            c0 = min(y for x, y in cells)
            c1 = max(y for x, y in cells)
            center = ((r0 + r1) // 2, (c0 + c1) // 2)
            for rr, cc in cells:
                out[rr][cc] = 0 if (rr, cc) == center else 3

    # Components of 1s enclosing an interior get a one-cell 8-neighbor halo.
    seen1 = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen1[r][c]:
                continue
            comp = [(r, c)]
            seen1[r][c] = True
            borders_inside = False
            for rr, cc in comp:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if (nr, nc) in interior:
                            borders_inside = True
                        if grid[nr][nc] == 1 and not seen1[nr][nc]:
                            seen1[nr][nc] = True
                            comp.append((nr, nc))
            if not borders_inside:
                continue
            for rr, cc in comp:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                                and (nr, nc) not in interior):
                            out[nr][nc] = 2

    return out
